<script setup lang="ts">
import { Head, Link, usePage } from '@inertiajs/vue3';
import { ArrowUpRight, Banknote, CalendarDays, CheckCircle2, CircleAlert, ClipboardList, CreditCard, PackageOpen, Plus, Users, Wallet } from '@lucide/vue';
import { computed, ref } from 'vue';
import PaymentDialog from '@/components/finance/PaymentDialog.vue';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { formatDate } from '@/lib/dates';
import { money } from '@/types/charge';
import type { Receivable } from '@/types/charge';

type Metrics = { active: number; returned_pending: number; ready_to_finalize: number; returned: number; today: number; overdue: number; balance: string; received: string; received_series: { label: string; value: number }[] };
const props = defineProps<{ today: string; metrics: Metrics; attention: Receivable[]; returnedPending: Receivable[]; recentContracts: Receivable[] }>();
const page = usePage<{ auth: { user: { name: string } } }>();
const paymentOpen = ref(false);
const paymentReceivable = ref<Receivable | null>(null);
const labels: Record<string, string> = { ACTIVE: 'Ativo', RETURNED: 'Devolvido', FINALIZED: 'Finalizado', CANCELLED: 'Cancelado' };
const firstName = computed(() => page.props.auth.user.name.split(' ')[0]);
const maxReceived = computed(() => Math.max(...props.metrics.received_series.map((item) => item.value), 1));
function pay(row: Receivable) { paymentReceivable.value = row; paymentOpen.value = true; }
function receivedLabel(value: number) { return money((value / 100).toFixed(2)); }
defineOptions({ layout: { breadcrumbs: [{ title: 'Dashboard', href: '/dashboard' }] } });
</script>

<template>
    <Head title="Dashboard" />
    <div class="dashboard-page mx-auto flex w-full max-w-[1600px] flex-col gap-7 p-4 sm:p-6 lg:gap-8 lg:p-8">
        <header class="dashboard-header flex flex-wrap items-end justify-between gap-5">
            <div><p class="dashboard-eyebrow">Visão geral · Locafy</p><h1 class="mt-2 text-3xl font-semibold tracking-[-.045em] sm:text-4xl">Olá, {{ firstName }}</h1><p class="mt-2 text-sm text-muted-foreground">{{ formatDate(today) }} · Veja o que precisa da sua atenção.</p></div>
            <Button as-child class="h-10 rounded-lg px-4 shadow-sm"><Link href="/contracts/create"><Plus class="mr-2 size-4" /> Novo contrato</Link></Button>
        </header>

        <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            <Link href="/contracts?status=ACTIVE" class="kpi-card kpi-blue"><div class="kpi-top"><span>Contratos ativos</span><span class="kpi-icon"><ClipboardList class="size-4" /></span></div><strong>{{ metrics.active }}</strong><small>{{ metrics.returned_pending }} pendentes · {{ metrics.ready_to_finalize }} prontos para finalizar</small></Link>
            <Link href="/contracts?status=PAYMENT_PENDING" class="kpi-card kpi-amber"><div class="kpi-top"><span>Devolvidos pendentes</span><span class="kpi-icon"><Wallet class="size-4" /></span></div><strong>{{ metrics.returned_pending }}</strong><small>Contratos devolvidos com saldo</small></Link>
            <Link href="/charges?filter=today" class="kpi-card kpi-sky"><div class="kpi-top"><span>Cobranças de hoje</span><span class="kpi-icon"><CalendarDays class="size-4" /></span></div><strong>{{ metrics.today }}</strong><small>Vencimentos na data atual</small></Link>
            <Link href="/charges?filter=overdue" class="kpi-card kpi-rose"><div class="kpi-top"><span>Em atraso</span><span class="kpi-icon"><CircleAlert class="size-4" /></span></div><strong>{{ metrics.overdue }}</strong><small>Contratos com saldo pendente</small></Link>
            <Link href="/charges" class="kpi-card kpi-primary"><div class="kpi-top"><span>Saldo a receber</span><span class="kpi-icon"><Wallet class="size-4" /></span></div><strong>{{ money(metrics.balance) }}</strong><small>Saldo atual de contratos abertos</small></Link>
            <div class="kpi-card kpi-green"><div class="kpi-top"><span>Recebido no mês</span><span class="kpi-icon"><Banknote class="size-4" /></span></div><strong>{{ money(metrics.received) }}</strong><small>Pagamentos registrados</small></div>
        </section>

        <section class="grid items-start gap-6 xl:grid-cols-[1.35fr_.65fr]">
            <Card class="dashboard-card overflow-hidden"><CardHeader class="flex flex-row items-start justify-between gap-4 pb-2"><div><CardTitle>Recebimentos</CardTitle><p class="mt-1 text-xs text-muted-foreground">Valor recebido nos últimos sete dias.</p></div><div class="chart-legend"><span /> Recebido</div></CardHeader><CardContent><div class="revenue-chart"><div v-for="item in metrics.received_series" :key="item.label" class="chart-column"><div class="chart-value" :class="{ 'opacity-0': item.value === 0 }">{{ receivedLabel(item.value) }}</div><div class="chart-track"><div class="chart-bar" :style="{ height: `${Math.max((item.value / maxReceived) * 100, item.value ? 12 : 3)}%` }" /></div><span>{{ item.label }}</span></div></div></CardContent></Card>
            <Card class="dashboard-card"><CardHeader><CardTitle>Resumo da operação</CardTitle><p class="mt-1 text-xs text-muted-foreground">Sinais que ajudam a priorizar o dia.</p></CardHeader><CardContent class="space-y-3"><Link href="/contracts?status=RETURNED" class="summary-row"><span class="summary-icon bg-blue-50 text-primary dark:bg-primary/15"><PackageOpen class="size-4" /></span><span><strong>Devolvidos</strong><small>{{ metrics.returned }} contratos no total</small></span><ArrowUpRight class="ml-auto size-4 text-muted-foreground" /></Link><Link href="/charges?filter=overdue" class="summary-row"><span class="summary-icon bg-amber-50 text-amber-600 dark:bg-amber-400/15"><CircleAlert class="size-4" /></span><span><strong>Em atraso</strong><small>{{ metrics.overdue }} cobranças para acompanhar</small></span><ArrowUpRight class="ml-auto size-4 text-muted-foreground" /></Link><Link href="/pagamentos" class="summary-row"><span class="summary-icon bg-emerald-50 text-emerald-600 dark:bg-emerald-400/15"><CreditCard class="size-4" /></span><span><strong>Recebimentos</strong><small>{{ money(metrics.received) }} no mês</small></span><ArrowUpRight class="ml-auto size-4 text-muted-foreground" /></Link></CardContent></Card>
        </section>

        <section v-if="returnedPending.length" class="dashboard-card attention-panel"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="dashboard-eyebrow text-amber-600 dark:text-amber-400">Precisa de atenção</p><h2 class="mt-1 text-lg font-semibold tracking-[-.025em]">Devolvidos com saldo pendente</h2><p class="mt-1 text-xs text-muted-foreground">Contratos devolvidos que ainda precisam de quitação.</p></div><Button variant="ghost" size="sm" as-child><Link href="/contracts?status=PAYMENT_PENDING">Ver todos <ArrowUpRight class="ml-1 size-4" /></Link></Button></div><div class="mt-5 grid gap-2"> <div v-for="row in returnedPending" :key="row.id" class="attention-row"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><p class="truncate text-sm font-semibold">{{ row.client }}</p><Badge variant="warning">Contrato #{{ row.contract_id }}</Badge></div><p class="mt-1 text-xs text-muted-foreground">Devolução {{ formatDate(row.ended_at) }} · Pago {{ money(row.total_paid) }} · Descontos {{ money(row.total_discount) }}</p></div><div class="flex items-center gap-3"><strong class="text-sm tabular-nums text-primary">{{ money(row.balance) }}</strong><Button size="sm" variant="outline" as-child><Link :href="`/contracts/${row.contract_id}`">Abrir</Link></Button><Button size="sm" @click="pay(row)">Pagar</Button></div></div></div></section>
        <section v-else class="dashboard-card empty-attention"><CheckCircle2 class="size-5 text-emerald-500" /><div><strong>Tudo em dia</strong><p>Nenhuma cobrança pendente para acompanhar.</p></div></section>

        <section class="grid items-start gap-6 xl:grid-cols-[1.05fr_.95fr]">
            <Card class="dashboard-card"><CardHeader class="flex flex-row items-center justify-between"><div><CardTitle>Contratos recentes</CardTitle><p class="mt-1 text-xs text-muted-foreground">As últimas operações da empresa.</p></div><Button variant="ghost" size="sm" as-child><Link href="/contracts">Ver todos <ArrowUpRight class="ml-1 size-4" /></Link></Button></CardHeader><CardContent class="space-y-1"><Link v-for="row in recentContracts" :key="row.id" :href="`/contracts/${row.id}`" class="recent-row"><span class="recent-mark"><ClipboardList class="size-4" /></span><span class="min-w-0 flex-1"><strong>{{ row.client }}</strong><small>Contrato #{{ row.id }} · {{ formatDate(row.started_at) }}</small></span><Badge :variant="row.contract_status === 'ACTIVE' ? 'success' : 'muted'">{{ row.display_status_label ?? labels[row.contract_status] }}</Badge></Link><div v-if="!recentContracts.length" class="empty-state"><ClipboardList class="mx-auto mb-3 size-6" /><p>Sua operação começa aqui</p><small>Crie o primeiro contrato para acompanhar suas locações.</small></div></CardContent></Card>
            <Card class="dashboard-card"><CardHeader><CardTitle>Atalhos rápidos</CardTitle><p class="mt-1 text-xs text-muted-foreground">Ações frequentes da operação.</p></CardHeader><CardContent class="grid gap-2 sm:grid-cols-2"><Link v-for="item in [{ label: 'Novo contrato', href: '/contracts/create', icon: Plus }, { label: 'Novo cliente', href: '/clients/create', icon: Users }, { label: 'Cobranças', href: '/charges', icon: Wallet }, { label: 'Movimentações', href: '/movements', icon: PackageOpen }]" :key="item.href" :href="item.href" class="quick-action"><span><component :is="item.icon" class="size-4" /></span><strong>{{ item.label }}</strong><ArrowUpRight class="ml-auto size-4 text-muted-foreground" /></Link></CardContent></Card>
        </section>
        <PaymentDialog v-model:open="paymentOpen" :receivable="paymentReceivable" />
    </div>
</template>

<style>
.dashboard-page { font-family: Instrument Sans, ui-sans-serif, system-ui, sans-serif; }
.dashboard-eyebrow { color: hsl(var(--primary)); font-size: 10px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.kpi-card { min-height: 154px; border: 1px solid hsl(var(--border)); border-radius: 14px; padding: 18px; transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease; }.kpi-card:hover { transform: translateY(-2px); border-color: hsl(var(--primary) / .3); box-shadow: 0 12px 28px hsl(220 30% 20% / .08); }.kpi-top { display:flex; align-items:center; justify-content:space-between; color:hsl(var(--muted-foreground)); font-size:12px; font-weight:600; }.kpi-icon { display:flex; width:30px; height:30px; align-items:center; justify-content:center; border-radius:9px; }.kpi-card strong { display:block; margin-top:18px; color:hsl(var(--foreground)); font-size:25px; font-weight:700; letter-spacing:-.05em; }.kpi-card small { display:block; margin-top:7px; color:hsl(var(--muted-foreground)); font-size:11px; line-height:1.4; }.kpi-blue { background:hsl(214 95% 97%); }.kpi-blue .kpi-icon { background:#dcebff; color:#208AEF; }.kpi-sky { background:hsl(199 89% 97%); }.kpi-sky .kpi-icon { background:#d9f1fb; color:#168bb8; }.kpi-amber { background:hsl(38 92% 97%); }.kpi-amber .kpi-icon,.kpi-rose .kpi-icon { background:#ffedcf; color:#c47a0b; }.kpi-rose { background:hsl(20 100% 98%); }.kpi-primary { background:hsl(221 83% 96%); border-color:hsl(var(--primary) / .16); }.kpi-primary .kpi-icon { background:#dce9ff; color:hsl(var(--primary)); }.kpi-green { background:hsl(160 55% 96%); }.kpi-green .kpi-icon { background:#d9f4e8; color:#16875e; }
.dashboard-card { border-radius:14px; box-shadow:0 5px 22px rgba(15,23,42,.06); }.revenue-chart { display:grid; min-height:225px; grid-template-columns:repeat(7,minmax(0,1fr)); align-items:end; gap:12px; padding-top:15px; }.chart-column { display:flex; min-width:0; height:190px; flex-direction:column; align-items:center; justify-content:end; gap:8px; color:var(--muted-foreground); font-size:10px; }.chart-track { display:flex; width:100%; max-width:38px; height:145px; align-items:end; overflow:hidden; border-radius:8px 8px 3px 3px; background:color-mix(in srgb,var(--muted) 65%,transparent); }.chart-bar { width:100%; border-radius:8px 8px 3px 3px; background:linear-gradient(180deg,#61b6ff,#208AEF); transition:height .35s ease; }.chart-value { max-width:66px; overflow:hidden; color:var(--muted-foreground); font-size:9px; text-overflow:ellipsis; white-space:nowrap; }.chart-legend { display:flex; align-items:center; gap:6px; color:var(--muted-foreground); font-size:10px; }.chart-legend span { width:7px; height:7px; border-radius:50%; background:#208AEF; }
.summary-row,.recent-row,.quick-action { display:flex; align-items:center; gap:11px; border-radius:10px; padding:10px; transition:background .2s ease, transform .2s ease; }.summary-row:hover,.recent-row:hover,.quick-action:hover { background:color-mix(in srgb,var(--muted) 60%,transparent); transform:translateX(2px); }.summary-icon,.recent-mark,.quick-action > span { display:flex; width:32px; height:32px; flex:none; align-items:center; justify-content:center; border-radius:9px; }.summary-row strong,.summary-row small,.recent-row strong,.recent-row small { display:block; }.summary-row strong,.recent-row strong { color:var(--foreground); font-size:12px; font-weight:650; }.summary-row small,.recent-row small { margin-top:3px; color:var(--muted-foreground); font-size:10px; }.recent-mark { background:color-mix(in srgb,var(--primary) 10%,transparent); color:var(--primary); }.attention-panel { border:1px solid rgba(245,158,11,.22); border-radius:14px; background:linear-gradient(135deg,#fffbeb,var(--card)); padding:22px; }.attention-row { display:flex; align-items:center; justify-content:space-between; gap:14px; border-top:1px solid rgba(180,120,20,.25); padding:12px 0; }.empty-attention { display:flex; align-items:center; gap:12px; border:1px dashed var(--border); padding:18px 22px; }.empty-attention strong { font-size:13px; }.empty-attention p,.empty-state small { display:block; margin-top:3px; color:var(--muted-foreground); font-size:11px; }.empty-state { border:1px dashed var(--border); border-radius:10px; padding:30px 18px; text-align:center; color:var(--muted-foreground); font-size:12px; }.quick-action { border:1px solid var(--border); padding:13px; }.quick-action > span { background:color-mix(in srgb,var(--primary) 9%,transparent); color:var(--primary); }.quick-action strong { color:var(--foreground); font-size:12px; }
.dark .kpi-blue { background:#122b4a; border-color:#214c79; }.dark .kpi-blue .kpi-icon { background:#1b4774; color:#7ec3ff; }.dark .kpi-amber { background:#332715; border-color:#62491d; }.dark .kpi-amber .kpi-icon { background:#5a4016; color:#f4c56a; }.dark .kpi-sky { background:#102e3c; border-color:#1c5369; }.dark .kpi-sky .kpi-icon { background:#16495d; color:#76d4f4; }.dark .kpi-rose { background:#351f20; border-color:#69383a; }.dark .kpi-rose .kpi-icon { background:#5b2b2e; color:#ff9b92; }.dark .kpi-primary { background:#12376b; border-color:#2868aa; }.dark .kpi-primary .kpi-icon { background:#1e568c; color:#a8d5ff; }.dark .kpi-green { background:#123329; border-color:#245944; }.dark .kpi-green .kpi-icon { background:#1a4b38; color:#83ddb1; }.dark .kpi-card strong { color:#f8fafc; }.dark .kpi-card small,.dark .kpi-top { color:#c2cfdf; }.dark .dashboard-card { box-shadow:0 10px 30px rgba(0,0,0,.2); }.dark .attention-panel { background:linear-gradient(135deg,#302614,var(--card)); border-color:#6a4c1f; }.dark .attention-row { border-top-color:rgba(245,190,75,.2); }.dark .chart-track { background:#1c2b3d; }.dark .chart-bar { background:linear-gradient(180deg,#8acbff,#208AEF); }.dark .chart-value,.dark .chart-column,.dark .chart-legend { color:#b9c8d9; }
@media (prefers-reduced-motion: reduce) { .kpi-card,.summary-row,.recent-row,.quick-action,.chart-bar { transition:none; } }
@media (max-width:640px) { .attention-row { align-items:flex-start; flex-direction:column; }.attention-row > div:last-child { width:100%; justify-content:space-between; }.revenue-chart { gap:6px; }.chart-value { display:none; } }
</style>
